public class HiddenMatrix {
    public static void main (String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int[] min = new int[n+1];
        Arrays.fill(min, 1 << 30);
        for (int bit = 0; bit < 10; bit++) {
            for (int val = 0; val <= 1; val++) {
                ArrayList<Integer> query = new ArrayList<>();
                for (int i = 1; i <= n; i++) {
                    if (((i >> bit) & 1) == val) {
                        query.add(i);
                    }
                }
                if (query.size() != n && query.size() != 0) {
                    out.println(query.size());
                    for (int j = 0; j < query.size(); j++) {
                        if (j != 0) out.print(" ");
                        out.print(query.get(j));
                    }
                    out.println();
                    out.flush();

                    for (int i = 1; i <= n; i++) {
                        int d = in.nextInt();
                        if (((i >> bit) & 1) == 1 - val) {
                            min[i] = Math.min(min[i], d);
                        }
                    }
                }
            }
        }

        out.println(-1);
        for (int i = 1; i <= n; i++) {
            if (i != 1) out.print(" ");
            out.print(min[i]);
        }
        out.println();
        out.flush();
        System.exit(0);
    }
